/**
 * The rules of a provider's job screens — repair, pet care, helping — as
 * platform-free logic, used by the websites (Worker*JobPage, useLiveTrip,
 * JobChat, RateCustomerCard, SOSButton, GiveBackCard) and the apps alike.
 * What the next step is, which code it needs, what is owed and when, where
 * the trip goes: one copy, so the phone and the web never disagree.
 *
 * Keep this file free of browser APIs: the apps load it too.
 */
import { billTipPaise, surgeOnBill } from './money';

/* ── Repair ─────────────────────────────────────────────────────────── */

/**
 * Which handover code, if any, the NEXT repair step demands. Mirrors
 * OTP_GATES in the server's handover.service.js (the server refuses anyway;
 * this shows the code box before the button would be rejected).
 */
export function repairGateFor(nextStatus, serviceMode) {
  const atCustomer = ['doorstep', 'roadside', 'diagnosis_only'];
  const gates = {
    DIAGNOSING: atCustomer,
    REPAIR_IN_PROGRESS: atCustomer,
    DEVICE_PICKED_UP: ['pickup_repair'],
    COMPLETED: ['pickup_repair', 'workshop'],
  };
  const kind = { DIAGNOSING: 'start', REPAIR_IN_PROGRESS: 'start', DEVICE_PICKED_UP: 'handover', COMPLETED: 'return' }[nextStatus];
  if (!kind) return null;
  return gates[nextStatus].includes(serviceMode) ? kind : null;
}

export const REPAIR_GATE_COPY = {
  start: { title: 'Code to start work', hint: 'Ask the customer for their 6-digit code' },
  handover: { title: 'Code to collect the device', hint: 'The customer reads this out as they hand it over' },
  return: { title: 'Code to hand the device back', hint: 'Let them check the device first, then ask' },
};

/** The single next step for a repair, from its status AND how it's being done. */
export function repairNextAction(status, serviceMode) {
  const collecting = serviceMode === 'pickup_repair';
  const map = {
    PROVIDER_ASSIGNED: { to: 'WORKER_ACCEPTED', label: 'Accept job' },
    WORKER_ACCEPTED: collecting ? { to: 'PICKUP_SCHEDULED', label: 'Schedule the pickup' } : { to: 'ON_THE_WAY', label: 'Start trip' },
    ON_THE_WAY: { to: 'ARRIVED', label: "I've arrived" },
    ARRIVED: { to: 'DIAGNOSING', label: 'Start diagnosis' },
    DIAGNOSING: { to: 'REPAIR_IN_PROGRESS', label: 'Start repair' },
    APPROVED: { to: 'REPAIR_IN_PROGRESS', label: 'Start repair' },
    REPAIR_IN_PROGRESS: { to: 'QA_PENDING', label: 'Finish repair — run QA' },
    QA_PENDING: collecting ? { to: 'READY_FOR_RETURN', label: 'Ready to return' } : { to: 'COMPLETED', label: 'Complete job' },
    PICKUP_SCHEDULED: { to: 'DEVICE_PICKED_UP', label: 'Device collected' },
    DEVICE_PICKED_UP: { to: 'AT_WORKSHOP', label: 'Arrived at workshop' },
    AT_WORKSHOP: { to: 'DIAGNOSING', label: 'Start diagnosis' },
    READY_FOR_RETURN: { to: 'OUT_FOR_RETURN', label: 'Out for return' },
    OUT_FOR_RETURN: { to: 'COMPLETED', label: 'Delivered — complete' },
  };
  return map[status] || null;
}

/** Statuses where a quote can be raised. */
export const REPAIR_QUOTABLE = ['ARRIVED', 'DIAGNOSING', 'AT_WORKSHOP', 'REPAIR_IN_PROGRESS'];
/** Where the finished-repair photos are taken. */
export const REPAIR_PHOTO_STAGES = ['QA_PENDING', 'READY_FOR_RETURN'];
export const REPAIR_ENDED = ['COMPLETED', 'CANCELLED', 'REJECTED', 'EXPIRED', 'FAILED', 'REFUNDED'];
/** No SOS before accepting or after the end. */
export const REPAIR_NO_SOS = ['PROVIDER_ASSIGNED', 'COMPLETED', 'CANCELLED', 'REJECTED', 'EXPIRED', 'FAILED'];

/** Money is due once the repair is finished, not when it is promised. */
export function repairReadyForPayment(booking) {
  return ['QA_PENDING', 'READY_FOR_RETURN', 'OUT_FOR_RETURN', 'COMPLETED'].includes(booking.status) || booking.paymentStatus === 'paid';
}

/** What the customer pays now: the job plus an earlier cancellation fee, boost, tip on the bill and surge. */
export function repairDue(booking) {
  const snap = booking.priceSnapshot || {};
  const carriedPaise = booking.carriedFee?.paise > 0 ? booking.carriedFee.paise : 0;
  const boostPaise = booking.boost?.paise > 0 ? booking.boost.paise : 0;
  const tipPaise = billTipPaise(booking);
  const surgePaise = surgeOnBill(booking);
  return { duePaise: (snap.totalPaise || 0) + carriedPaise + boostPaise + tipPaise + surgePaise, carriedPaise, boostPaise, tipPaise, surgePaise };
}

/** A shop's technician can pass a job back to the owner until they set out. */
export const canPassBackToShop = (booking, isOwner) => !isOwner && !!booking.shopId && ['CONFIRMED', 'PROVIDER_ASSIGNED'].includes(booking.status);

/** The price the customer agreed to, if one exists (not an estimate or inspection). */
export function repairAgreedPaise(snapshot = {}) {
  return (snapshot.subtotalPaise || 0) > 0 && snapshot.isEstimate !== true
    && !['diagnosis_required', 'inspection_only'].includes(snapshot.resolutionPath) ? snapshot.subtotalPaise : 0;
}

export const QUOTE_LINE_KINDS = ['part', 'labour', 'consumable', 'travel', 'pickup', 'return', 'other'];

/** Rupees as typed (digits and one dot). */
export const rupeesInput = (v) => String(v).replace(/[^\d.]/g, '').replace(/(\..*)\./g, '$1');

export function quoteTotalPaise(items) {
  return items.reduce((sum, i) => sum + Math.round((Number(i.priceRupees) || 0) * 100) * (Number(i.quantity) || 1), 0);
}

/** The quote lines to send, or the reason it can't be sent yet. */
export function quotePayload({ repairCode, summary, items, warrantyDays, additional, agreedPaise, replace, replaceReason }) {
  const clean = items
    .filter((i) => i.label.trim() && Number(i.priceRupees) > 0)
    .map((i) => ({ kind: i.kind, label: i.label.trim(), quantity: Number(i.quantity) || 1, unitPricePaise: Math.round(Number(i.priceRupees) * 100) }));
  if (!repairCode) return { error: 'Choose the repair you will do' };
  if (!summary.trim()) return { error: 'Describe what you found' };
  if (!clean.length) return { error: 'Add at least one line with a description and a price' };
  if (quoteTotalPaise(items) < 1000) return { error: 'The quote total must be at least ₹10. Check the prices you entered.' };
  if (agreedPaise && replace && replaceReason.trim().length < 5) return { error: 'Say why the agreed price has to change' };
  return {
    body: {
      diagnosisSummary: summary.trim(),
      repairCode,
      warrantyDays: Number(warrantyDays) || 0,
      items: clean,
      isAdditional: additional,
      ...(additional ? { foundNote: summary.trim() } : {}),
      ...(agreedPaise && replace ? { replacesAgreed: true, replaceReason: replaceReason.trim() } : {}),
    },
  };
}

/** The repairs to choose from when quoting an inspection, own list first. */
export function quoteRepairOptions(groups = []) {
  const seen = new Set();
  return groups.flatMap((g) => g.repairs).filter((r) => !seen.has(r.code) && seen.add(r.code))
    .sort((a, b) => Number(b.selected) - Number(a.selected) || a.name.localeCompare(b.name));
}

/** QA: what's still untested or failing among the required checks. */
export function qaState(items = [], results = {}) {
  return {
    requiredUntested: items.filter((i) => i.required && !results[i.code]),
    failedRequired: items.filter((i) => i.required && results[i.code] === 'fail'),
  };
}

export function qaPayload(checklist, results) {
  return {
    stage: 'after',
    checklistCode: checklist.code,
    results: (checklist.items || []).map((i) => ({ itemCode: i.code, label: i.label, required: i.required, result: results[i.code] || 'not_tested' })),
  };
}

