export const PET_NEXT = {
  PROVIDER_ACCEPTED: [['PROVIDER_EN_ROUTE', "I'm on my way"], ['SERVICE_STARTED', 'Start now (already there)']],
  PROVIDER_EN_ROUTE: [['PROVIDER_ARRIVED', "I've arrived"]],
  PROVIDER_ARRIVED: [['SERVICE_STARTED', 'Start the service']],
};
export const PET_DONE = ['SERVICE_COMPLETED', 'CUSTOMER_CONFIRMATION', 'PAYMENT_PENDING', 'PAYMENT_COMPLETED', 'CLOSED'];
export const PET_PAY_STAGES = ['SERVICE_COMPLETED', 'CUSTOMER_CONFIRMATION', 'PAYMENT_PENDING', 'PAYMENT_COMPLETED'];
export const PET_LIVE = ['PROVIDER_ACCEPTED', 'PROVIDER_EN_ROUTE', 'PROVIDER_ARRIVED', 'PET_HANDOVER', 'SERVICE_STARTED', 'SERVICE_PAUSED'];

export function petDuePaise(booking) {
  return (booking.pricing?.totalPaise || 0) + (booking.carriedFee?.paise > 0 ? booking.carriedFee.paise : 0)
    + (booking.boost?.paise || 0) + billTipPaise(booking) + surgeOnBill(booking);
}

/** The first pet's handling brief, and whether it's flagged for biting or aggression. */
export function petBrief(booking) {
  const brief = booking.pets?.[0]?.snapshot?.handlingBrief || booking.pets?.[0]?.snapshot || {};
  const risky = ['medium', 'high'].includes(brief.biteRisk) || ['medium', 'high'].includes(brief.aggressionLevel);
  const level = brief.biteRisk === 'high' || brief.aggressionLevel === 'high' ? 'high' : 'medium';
  return { brief, risky, level };
}

/* ── Helping ────────────────────────────────────────────────────────── */

const HELPING_NEXT_STATUS = {
  WORKER_ACCEPTED: ['EN_ROUTE'], EN_ROUTE: ['ARRIVED'], ARRIVED: ['TASK_STARTED'],
  TASK_STARTED: ['IN_PROGRESS'], IN_PROGRESS: ['RETURNING'], RETURNING: ['AT_DROPOFF'],
};
export const isReturnTask = (task) => ['return', 'exchange'].includes(task.serviceType);
export const helpingPaidAt = (task) => (isReturnTask(task) ? ['IN_PROGRESS', 'RETURNING', 'AT_DROPOFF', 'HANDED_OVER'] : ['RETURNING', 'HANDED_OVER']);
export const helpingFinishesAt = (task) => (isReturnTask(task) ? ['HANDED_OVER'] : ['RETURNING', 'HANDED_OVER']);
export const HELPING_DONE = ['COMPLETED', 'CUSTOMER_CONFIRMED', 'SETTLED'];
export const HELPING_NO_SOS = ['COMPLETED', 'CUSTOMER_CONFIRMED', 'SETTLED', 'CANCELLED', 'FAILED', 'DISPUTED'];

export function helpingMoveLabel(status, task) {
  const labels = {
    EN_ROUTE: "I'm on my way",
    ARRIVED: "I've arrived",
    TASK_STARTED: 'Start the task',
    IN_PROGRESS: 'Begin',
    RETURNING: { return: 'Heading to the drop-off', exchange: 'Heading to the store', pickup: 'Collected, heading to the customer' }[task.serviceType] || 'Bought everything, heading to the customer',
    AT_DROPOFF: "I'm at the drop-off",
  };
  return labels[status] || status;
}

/** The steps a helper can take now: none while the customer is deciding, none before every item is settled. */
export function helpingNextMoves(task, due, pendingApproval) {
  const isReturn = isReturnTask(task);
  return (HELPING_NEXT_STATUS[task.status] || []).filter((s) => {
    if (s === 'RETURNING') return !pendingApproval && (isReturn || !due.itemsPending);
    if (s === 'AT_DROPOFF') return isReturn;
    return true;
  });
}

export const helpingItemDone = (item) => ['purchased', 'not_found', 'rejected', 'skipped'].includes(item.status);
export const HELPING_HANDED = ['HANDED_OVER', 'COMPLETED', 'CUSTOMER_CONFIRMED', 'SETTLED'];

/* ── Trips: where the provider is heading, for each kind ─────────────── */

const point = (p) => (p?.coordinates?.length === 2 ? { lng: p.coordinates[0], lat: p.coordinates[1], address: p.address || '' } : null);

export const TRIPS = {
  repair: (b) => {
    if (['ON_THE_WAY', 'PICKUP_SCHEDULED'].includes(b.status)) return { to: point(b.location), toCustomer: true };
    if (b.status === 'OUT_FOR_RETURN') return { to: point(b.location), toCustomer: true, returning: true };
    if (b.status === 'DEVICE_PICKED_UP') return { to: null, toCustomer: false };
    return null;
  },
  pet: (b) => {
    if (b.status === 'PROVIDER_EN_ROUTE') return { to: point(b.serviceLocation), toCustomer: true };
    if (b.status === 'SERVICE_STARTED' && b.serviceMode === 'transport') return { to: point(b.destination), toCustomer: false };
    return null;
  },
  helping: (t) => {
    const startsAtCustomer = ['return', 'exchange'].includes(t.serviceType);
    if (t.status === 'EN_ROUTE') return { to: point(t.pickupLocation), toCustomer: startsAtCustomer };
    if (t.status === 'RETURNING') return { to: point(t.destination) || point(t.pickupLocation), toCustomer: !startsAtCustomer };
    return null;
  },
};

export function tripOf(kind, job) {
  return job ? TRIPS[kind]?.(job) || null : null;
}

export const MOVING_STATUSES = ['ON_THE_WAY', 'OUT_FOR_RETURN', 'PICKUP_SCHEDULED', 'DEVICE_PICKED_UP'];

/** A stored GeoJSON point as { lat, lng, address }, for the job map. */
export function pointOf(loc) {
  const c = loc?.coordinates;
  return Array.isArray(c) && c.length === 2 && (c[0] || c[1]) ? { lat: c[1], lng: c[0], address: loc.address || '' } : null;
}

